create table public.personal_os_calendar_weeks(owner_id uuid not null references auth.users(id) on delete cascade,week_start date not null,tasks jsonb not null default '[]',sources jsonb not null default '[]',synced_at timestamptz not null default now(),primary key(owner_id,week_start));
alter table public.personal_os_calendar_weeks enable row level security;revoke all on public.personal_os_calendar_weeks from public,anon,authenticated;grant select on public.personal_os_calendar_weeks to authenticated;grant all on public.personal_os_calendar_weeks to service_role;create policy calendar_owner on public.personal_os_calendar_weeks for select to authenticated using((select auth.uid())=owner_id);
create table public.personal_os_calendar_edits(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,week_start date not null,task_id text not null,base_task jsonb not null,changes jsonb not null,status text not null default 'pending' check(status in('pending','applied','conflict','failed')),message text,created_at timestamptz not null default now(),verified_at timestamptz);
create unique index calendar_one_pending on public.personal_os_calendar_edits(owner_id,week_start,task_id) where status='pending';
alter table public.personal_os_calendar_edits enable row level security;revoke all on public.personal_os_calendar_edits from public,anon,authenticated;grant select on public.personal_os_calendar_edits to authenticated;grant all on public.personal_os_calendar_edits to service_role;create policy calendar_edit_owner on public.personal_os_calendar_edits for select to authenticated using((select auth.uid())=owner_id);
create function public.request_calendar_edit(p_week date,p_task text,p_base jsonb,p_changes jsonb) returns uuid language plpgsql security definer set search_path='' as $f$
declare t jsonb;request_id uuid;begin
if auth.uid() is null then raise exception 'Authentication required';end if;
select x into t from public.personal_os_calendar_weeks w,jsonb_array_elements(w.tasks) x where w.owner_id=auth.uid() and w.week_start=p_week and x->>'id'=p_task;
if t is null or t is distinct from p_base then raise exception 'Source changed; reload before editing';end if;
if jsonb_typeof(p_changes)<>'object' or (p_changes - array['title','group','date','status'])<>'{}'::jsonb or length(coalesce(p_changes->>'title','')) not between 1 and 500 or p_changes->>'group' not in ('Servicebio','Medtec / Biomedia','Ventures','Enexia','Language','Health','Finance','Learning','Personal','Other') or p_changes->>'status' not in('plan','doing','blocked','reported_done') then raise exception 'Invalid changes';end if;
if p_changes->>'date' is not null and ((p_changes->>'date')::date<p_week or (p_changes->>'date')::date>p_week+6) then raise exception 'Choose a day in this week';end if;
insert into public.personal_os_calendar_edits(owner_id,week_start,task_id,base_task,changes) values(auth.uid(),p_week,p_task,t,p_changes) returning id into request_id;return request_id;end $f$;
revoke all on function public.request_calendar_edit(date,text,jsonb,jsonb) from public,anon;grant execute on function public.request_calendar_edit(date,text,jsonb,jsonb) to authenticated;
